-- ----------------------------
-- Table structure for base_classification_node
-- ----------------------------
DROP TABLE IF EXISTS `base_classification_node`;
CREATE TABLE `base_classification_node`  (
  `classification_node_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分类节点ID',
  `classification_system_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所属分类体系ID',
  `node_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '节点编码：体系内唯一，可对接外部标准类目码',
  `node_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '节点名称',
  `parent_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '父节点ID：根节点为NULL',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态：0停用 1启用',
  `sort` int NOT NULL DEFAULT 0 COMMENT '排序号：升序排列',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `row_version` int NOT NULL DEFAULT 1 COMMENT '数据版本号：并发控制',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人ID',
  `create_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '删除标记：0正常 1删除',
  PRIMARY KEY (`classification_node_id`) USING BTREE,
  UNIQUE INDEX `uk_classification_node_code`(`classification_system_id` ASC, `node_code` ASC) USING BTREE,
  INDEX `idx_classification_node_parent`(`classification_system_id` ASC, `parent_id` ASC, `status` ASC, `del_flag` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '分类体系节点表：分类体系下的树形类目节点' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of base_classification_node
-- ----------------------------

-- ----------------------------
-- Table structure for base_classification_system
