DROP TABLE IF EXISTS `base_classification_system`;
CREATE TABLE `base_classification_system`  (
  `classification_system_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分类体系ID',
  `system_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '体系编码：全局唯一，作为公共选项查询入参',
  `system_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '体系名称：如财务分类、医保分类、电商分类',
  `sort` int NOT NULL DEFAULT 0 COMMENT '排序号：升序排列',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `row_version` int NOT NULL DEFAULT 1 COMMENT '数据版本号：并发控制',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人ID',
  `create_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '删除标记：0正常 1删除',
  PRIMARY KEY (`classification_system_id`) USING BTREE,
  UNIQUE INDEX `uk_classification_system_code`(`system_code` ASC) USING BTREE,
  INDEX `idx_classification_system_list`(`del_flag` ASC, `sort` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '分类体系表：定义多套独立层级分类的元数据' ROW_FORMAT = Dynamic;

