  `create_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`enterprise_role_id`) USING BTREE,
  UNIQUE INDEX `uk_base_enterprise_role`(`enterprise_id` ASC, `role_type` ASC) USING BTREE,
  INDEX `idx_base_enterprise_role_enterprise`(`enterprise_id` ASC) USING BTREE,
  INDEX `idx_base_enterprise_role_type`(`role_type` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '企业主体角色关系表' ROW_FORMAT = Dynamic;

