-- ----------------------------
-- Table structure for dev_story
-- ----------------------------
DROP TABLE IF EXISTS `dev_story`;
CREATE TABLE `dev_story`  (
  `story_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '需求id,UUID格式',
