  INDEX `idx_erp_inventory_batch_sku`(`sku_id` ASC) USING BTREE,
  INDEX `idx_erp_inventory_batch_no`(`batch_no` ASC) USING BTREE,
  INDEX `idx_erp_inventory_batch_expiry_date`(`expiry_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'ERP库存批次' ROW_FORMAT = Dynamic;

