-- Table structure for erp_inventory_movement
-- ----------------------------
DROP TABLE IF EXISTS `erp_inventory_movement`;
CREATE TABLE `erp_inventory_movement`  (
  `movement_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '库存流水ID',
  `balance_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '库存余额ID',
  `warehouse_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '仓库ID',
  `sku_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SKU ID',
  `batch_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '库存批次ID',
  `source_bill_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源单据类型',
  `source_bill_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源单据ID',
  `source_bill_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源单据号',
  `movement_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '库存业务类型',
  `direction` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '方向：IN入库 OUT出库',
  `before_package_unit_count` int NOT NULL COMMENT '变更前包装单位数量',
  `change_package_unit_count` int NOT NULL COMMENT '变更包装单位数量',
  `after_package_unit_count` int NOT NULL COMMENT '变更后包装单位数量',
  `before_min_unit_count` bigint NOT NULL COMMENT '变更前最小单位数量',
  `change_min_unit_count` bigint NOT NULL COMMENT '变更最小单位数量',
  `after_min_unit_count` bigint NOT NULL COMMENT '变更后最小单位数量',
  `package_unit_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '包装单位名称',
  `min_unit_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '最小单位名称',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `operator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '操作人ID',
  `create_date` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`movement_id`) USING BTREE,
  INDEX `idx_erp_inventory_movement_balance_date`(`balance_id` ASC, `create_date` ASC) USING BTREE,
  INDEX `idx_erp_inventory_movement_source`(`source_bill_type` ASC, `source_bill_no` ASC) USING BTREE,
  INDEX `idx_erp_inventory_movement_warehouse_sku`(`warehouse_id` ASC, `sku_id` ASC) USING BTREE,
  INDEX `idx_erp_inventory_movement_batch`(`batch_id` ASC) USING BTREE,
  INDEX `idx_erp_inventory_movement_owner_date`(`operator_id` ASC, `create_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'ERP库存流水' ROW_FORMAT = Dynamic;

