  `movement_trace_code_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '库存流水追溯码关联记录ID',
  `movement_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联库存流水ID',
  `trace_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联追溯码记录ID',
  `create_date` datetime NULL DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`movement_trace_code_id`) USING BTREE,
  UNIQUE INDEX `uk_erp_inventory_movement_trace`(`movement_id` ASC, `trace_id` ASC) USING BTREE,
  INDEX `idx_erp_inventory_trace_history`(`trace_id` ASC, `movement_id` ASC) USING BTREE
