-- Records of erp_inventory_movement_trace_code
-- ----------------------------

-- ----------------------------
-- Table structure for erp_inventory_trace_code
-- ----------------------------
DROP TABLE IF EXISTS `erp_inventory_trace_code`;
CREATE TABLE `erp_inventory_trace_code`  (
  `trace_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '追溯码记录ID',
  `trace_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '追溯码',
  `sku_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联产品品规SKU ID',
  `batch_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联库存批次ID',
  `current_balance_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '当前所在库存余额ID，出库后为空',
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '追溯码库存状态',
  `package_level` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SMALL' COMMENT '包装层级：SMALL小码，MEDIUM中码和LARGE大码为预留层级',
  `parent_trace_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '上级包装追溯码ID，预留用于大小码包装关联',
  `row_version` int NOT NULL DEFAULT 1 COMMENT '并发控制版本号',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '最后修改人ID',
  `create_date` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_date` datetime NULL DEFAULT NULL COMMENT '最后修改时间',
  PRIMARY KEY (`trace_id`) USING BTREE,
  UNIQUE INDEX `uk_erp_inventory_trace_code`(`trace_code` ASC) USING BTREE,
  INDEX `idx_erp_inventory_trace_current_balance_status`(`current_balance_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_erp_inventory_trace_sku_status`(`sku_id` ASC, `status` ASC) USING BTREE,
