-- ----------------------------
-- Table structure for erp_purchase_order
-- ----------------------------
DROP TABLE IF EXISTS `erp_purchase_order`;
CREATE TABLE `erp_purchase_order`  (
  `purchase_order_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '采购单ID',
  `purchase_order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '采购单号',
  `supplier_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '供应商企业主体ID',
  `supplier_name_snapshot` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '供应商名称快照',
  `warehouse_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '目标仓库ID',
  `order_date` date NOT NULL COMMENT '采购日期',
  `expected_arrival_date` date NULL DEFAULT NULL COMMENT '预计到货日期',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '采购单状态：DRAFT草稿、WAITING_RECEIPT待收货、PARTIAL_RECEIPT部分入库、COMPLETED已完成、CANCELLED已取消、CLOSED已关闭',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '采购单备注',
  `row_version` int NOT NULL DEFAULT 1 COMMENT '并发控制版本号',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '最后修改人ID',
  `confirmed_by` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '确认人ID',
  `confirmed_at` datetime NULL DEFAULT NULL COMMENT '确认时间',
  `create_date` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_date` datetime NULL DEFAULT NULL COMMENT '最后修改时间',
  PRIMARY KEY (`purchase_order_id`) USING BTREE,
  UNIQUE INDEX `uk_erp_purchase_order_no`(`purchase_order_no` ASC) USING BTREE,
  INDEX `idx_erp_purchase_order_supplier_status`(`supplier_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_erp_purchase_order_warehouse_status`(`warehouse_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_erp_purchase_order_date`(`order_date` ASC) USING BTREE,
  INDEX `idx_erp_purchase_order_owner_date`(`creator_id` ASC, `create_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'ERP采购单' ROW_FORMAT = Dynamic;

