  `spec_name_snapshot` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '产品规格名称快照',
  `package_spec_snapshot` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '包装规格快照',
  `package_unit_snapshot` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '包装单位名称快照',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '采购明细备注',
  `create_date` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_date` datetime NULL DEFAULT NULL COMMENT '最后修改时间',
  PRIMARY KEY (`purchase_order_item_id`) USING BTREE,
  UNIQUE INDEX `uk_erp_purchase_order_item_sku`(`purchase_order_id` ASC, `sku_id` ASC) USING BTREE,
  UNIQUE INDEX `uk_erp_purchase_order_item_line`(`purchase_order_id` ASC, `line_no` ASC) USING BTREE,
  INDEX `idx_erp_purchase_order_item_sku`(`sku_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'ERP采购单明细' ROW_FORMAT = Dynamic;

