-- ----------------------------
-- Table structure for erp_purchase_order_log
-- ----------------------------
DROP TABLE IF EXISTS `erp_purchase_order_log`;
CREATE TABLE `erp_purchase_order_log`  (
  `purchase_order_log_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '采购单日志ID',
  `purchase_order_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '采购单ID',
  `action_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '操作类型：CREATE创建、UPDATE修改、CONFIRM确认、INBOUND入库、CANCEL取消、CLOSE关闭',
  `from_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '操作前采购单状态',
  `to_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '操作后采购单状态',
  `summary` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务操作摘要',
  `related_inbound_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联采购入库单ID',
  `related_inbound_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联采购入库单号',
  `reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '取消或关闭原因',
  `operator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '操作人ID',
  `operated_at` datetime NOT NULL COMMENT '操作时间',
  PRIMARY KEY (`purchase_order_log_id`) USING BTREE,
  INDEX `idx_erp_purchase_order_log_order_time`(`purchase_order_id` ASC, `operated_at` ASC) USING BTREE,
  INDEX `idx_erp_purchase_order_log_inbound`(`related_inbound_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'ERP采购单业务日志' ROW_FORMAT = Dynamic;

