DROP TABLE IF EXISTS `erp_warehouse`;
CREATE TABLE `erp_warehouse`  (
  `warehouse_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '仓库ID',
  `warehouse_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '仓库编码',
  `warehouse_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '仓库名称',
  `warehouse_name_normalized` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '仓库名称规范化值',
  `storage_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '仓库储存类型: NORMAL普通 REFRIGERATED冷藏 FROZEN冷冻 COOL阴凉 HAZARDOUS危险品',
  `business_scope` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '仓库业务范围: DRUG药品 CONSUMABLE耗材 DEVICE器械 COMPREHENSIVE综合',
  `address` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '地址',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态: 0停用 1启用',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `row_version` int NOT NULL DEFAULT 1 COMMENT '数据版本号',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人ID',
  `create_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '删除标记: 0正常 1删除',
  PRIMARY KEY (`warehouse_id`) USING BTREE,
  UNIQUE INDEX `uk_erp_warehouse_code`(`warehouse_code` ASC) USING BTREE,
  INDEX `idx_erp_warehouse_name`(`warehouse_name_normalized` ASC, `del_flag` ASC) USING BTREE,
  INDEX `idx_erp_warehouse_storage_type`(`storage_type` ASC, `del_flag` ASC) USING BTREE,
  INDEX `idx_erp_warehouse_business_scope`(`business_scope` ASC, `del_flag` ASC) USING BTREE,
  INDEX `idx_erp_warehouse_status`(`status` ASC, `del_flag` ASC) USING BTREE,
  INDEX `idx_erp_warehouse_update_date`(`update_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'ERP仓库基础资料表' ROW_FORMAT = Dynamic;

