  INDEX `idx_erp_warehouse_zone_warehouse_name`(`warehouse_id` ASC, `zone_name_normalized` ASC, `del_flag` ASC) USING BTREE,
  INDEX `idx_erp_warehouse_zone_update_date`(`update_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '仓库库区基础资料表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of erp_warehouse_zone
-- ----------------------------

-- ----------------------------
-- Table structure for med_department
-- ----------------------------
DROP TABLE IF EXISTS `med_department`;
CREATE TABLE `med_department`  (
  `department_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '临床科室ID',
  `department_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '临床科室编码',
  `department_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '临床科室名称',
  `pid` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '上级临床科室ID',
  `sort` int NOT NULL DEFAULT 0 COMMENT '排序，升序',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态 0停用 1启用',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人ID',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '删除标记 0正常 1删除',
  PRIMARY KEY (`department_id`) USING BTREE,
  UNIQUE INDEX `uk_med_department_code`(`department_code` ASC) USING BTREE,
  INDEX `idx_med_department_pid`(`pid` ASC, `del_flag` ASC) USING BTREE,
  INDEX `idx_med_department_name`(`department_name` ASC) USING BTREE,
  INDEX `idx_med_department_status`(`status` ASC, `del_flag` ASC, `sort` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '临床科室' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of med_department
-- ----------------------------

-- ----------------------------
-- Table structure for med_diagnosis
-- ----------------------------
DROP TABLE IF EXISTS `med_diagnosis`;
CREATE TABLE `med_diagnosis`  (
  `diagnosis_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '疾病诊断档案ID（UUID）',
  `icd_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ICD编码',
  `icd_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ICD名称',
  `name_pinyin` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'ICD名称拼音',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态：0停用，1启用',
  `sort` int NOT NULL DEFAULT 0 COMMENT '排序号，数值越小越靠前',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人系统用户ID',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '最后修改人系统用户ID',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_date` datetime NOT NULL COMMENT '最后修改时间',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '删除标记：0未删除，1已删除',
  `active_icd_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS ((case when (`del_flag` = 0) then `icd_code` else NULL end)) STORED COMMENT '未删除诊断的ICD编码（唯一约束生成列）' NULL,
  PRIMARY KEY (`diagnosis_id`) USING BTREE,
  UNIQUE INDEX `uk_med_diagnosis_active_icd_code`(`active_icd_code` ASC) USING BTREE,
  INDEX `idx_med_diagnosis_status_sort`(`status` ASC, `del_flag` ASC, `sort` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '疾病诊断档案' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of med_diagnosis
-- ----------------------------

-- ----------------------------
-- Table structure for med_doctor
-- ----------------------------
DROP TABLE IF EXISTS `med_doctor`;
CREATE TABLE `med_doctor`  (
  `doctor_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '医生ID',
  `doctor_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '医生编号',
  `user_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '绑定系统用户ID',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '医生姓名',
  `name_pinyin` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '姓名拼音',
  `gender` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '性别，字典MED_DOCTOR_GENDER',
  `birth_date` date NULL DEFAULT NULL COMMENT '出生日期',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '工作联系电话',
  `email` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '工作邮箱',
  `avatar` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '头像URL',
  `professional_title` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '职称，字典MED_DOCTOR_TITLE',
  `administrative_position` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '行政职务',
  `employment_type` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用工类型，字典MED_EMPLOYMENT_TYPE',
  `practice_start_date` date NULL DEFAULT NULL COMMENT '开始从业日期',
  `employment_date` date NULL DEFAULT NULL COMMENT '入职日期',
  `departure_date` date NULL DEFAULT NULL COMMENT '离职日期',
  `expertise` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '擅长领域',
  `introduction` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '医生简介',
  `default_visit_minutes` smallint NOT NULL DEFAULT 15 COMMENT '默认接诊分钟数',
  `online_consultation` tinyint NOT NULL DEFAULT 0 COMMENT '是否支持线上问诊 0否 1是',
  `appointment_enabled` tinyint NOT NULL DEFAULT 1 COMMENT '是否允许预约 0否 1是',
  `profile_visible` tinyint NOT NULL DEFAULT 1 COMMENT '是否公开展示 0否 1是',
  `sort` int NOT NULL DEFAULT 0 COMMENT '展示排序，升序',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态 0停用 1启用',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '内部备注',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人ID',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '删除标记 0正常 1删除',
  `active_user_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS ((case when (`del_flag` = 0) then `user_id` else NULL end)) STORED COMMENT '未删除医生绑定用户ID（唯一约束生成列）' NULL,
  PRIMARY KEY (`doctor_id`) USING BTREE,
  UNIQUE INDEX `uk_med_doctor_no`(`doctor_no` ASC) USING BTREE,
  UNIQUE INDEX `uk_med_doctor_user`(`user_id` ASC) USING BTREE,
  UNIQUE INDEX `uk_med_doctor_active_user`(`active_user_id` ASC) USING BTREE,
  INDEX `idx_med_doctor_name`(`name` ASC) USING BTREE,
  INDEX `idx_med_doctor_title`(`professional_title` ASC) USING BTREE,
  INDEX `idx_med_doctor_status`(`status` ASC, `del_flag` ASC, `sort` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '医生基础档案' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of med_doctor
-- ----------------------------

-- ----------------------------
-- Table structure for med_doctor_department
-- ----------------------------
DROP TABLE IF EXISTS `med_doctor_department`;
CREATE TABLE `med_doctor_department`  (
  `doctor_department_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '医生出诊科室关系ID',
  `doctor_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '医生ID',
  `department_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '临床科室ID',
  `is_primary` tinyint NOT NULL DEFAULT 0 COMMENT '是否主科室 0否 1是',
  `department_position` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '医生在该科室的职务',
  `appointment_enabled` tinyint NOT NULL DEFAULT 1 COMMENT '该科室是否允许预约 0否 1是',
  `valid_from` date NULL DEFAULT NULL COMMENT '关系生效日期',
  `valid_to` date NULL DEFAULT NULL COMMENT '关系失效日期',
  `sort` int NOT NULL DEFAULT 0 COMMENT '排序，升序',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态 0停用 1启用',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人ID',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '删除标记 0正常 1删除',
  PRIMARY KEY (`doctor_department_id`) USING BTREE,
  UNIQUE INDEX `uk_med_doctor_department`(`doctor_id` ASC, `department_id` ASC) USING BTREE,
  INDEX `idx_med_doctor_department_dept`(`department_id` ASC, `status` ASC, `del_flag` ASC) USING BTREE,
  INDEX `idx_med_doctor_department_primary`(`doctor_id` ASC, `is_primary` ASC, `status` ASC, `del_flag` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '医生出诊科室' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of med_doctor_department
-- ----------------------------

-- ----------------------------
-- Table structure for med_outpatient_diagnosis
-- ----------------------------
DROP TABLE IF EXISTS `med_outpatient_diagnosis`;
CREATE TABLE `med_outpatient_diagnosis`  (
  `record_diagnosis_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '病历诊断明细ID（UUID）',
  `record_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '门诊病历ID',
  `diagnosis_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '疾病诊断档案ID',
  `icd_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '提交病历时的ICD编码快照',
  `icd_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '提交病历时的ICD名称快照',
  `is_primary` tinyint NOT NULL DEFAULT 0 COMMENT '是否主要诊断：0否，1是',
  `sort` int NOT NULL DEFAULT 0 COMMENT '病历内排序号',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人系统用户ID',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`record_diagnosis_id`) USING BTREE,
  UNIQUE INDEX `uk_med_outpatient_diagnosis_record_diagnosis`(`record_id` ASC, `diagnosis_id` ASC) USING BTREE,
  INDEX `idx_med_outpatient_diagnosis_record_sort`(`record_id` ASC, `is_primary` ASC, `sort` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '门诊病历诊断明细' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of med_outpatient_diagnosis
-- ----------------------------

-- ----------------------------
-- Table structure for med_outpatient_record
-- ----------------------------
DROP TABLE IF EXISTS `med_outpatient_record`;
CREATE TABLE `med_outpatient_record`  (
  `record_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '门诊病历ID（UUID）',
  `registration_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '挂号单ID，一条挂号单最多一份门诊病历',
  `patient_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '患者ID',
  `doctor_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '接诊医生ID',
  `department_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '接诊科室ID',
  `visit_type` smallint NULL DEFAULT NULL COMMENT '就诊类型：0初诊，10复诊',
  `informant` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '病史陈述者',
  `temperature` decimal(4, 1) NULL DEFAULT NULL COMMENT '体温（摄氏度）',
  `pulse` smallint NULL DEFAULT NULL COMMENT '脉搏（次/分钟）',
  `respiratory_rate` smallint NULL DEFAULT NULL COMMENT '呼吸频率（次/分钟）',
  `systolic_pressure` smallint NULL DEFAULT NULL COMMENT '收缩压（mmHg）',
  `diastolic_pressure` smallint NULL DEFAULT NULL COMMENT '舒张压（mmHg）',
  `height` decimal(5, 2) NULL DEFAULT NULL COMMENT '身高（cm）',
  `weight` decimal(5, 2) NULL DEFAULT NULL COMMENT '体重（kg）',
  `chief_complaint` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '主诉',
  `present_illness` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '现病史',
  `past_history` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '既往史',
  `personal_history` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '个人史',
  `family_history` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '家族史',
  `allergy_history` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '过敏史',
  `marital_reproductive` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '婚育史',
  `menstrual_history` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '月经史',
  `physical_examination` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '体格检查',
  `specialist_examination` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '专科检查',
  `auxiliary_examination` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '辅助检查结果',
  `treatment_plan` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '处理方案',
  `medical_advice` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '医嘱',
  `follow_up_advice` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '复诊建议',
  `remark` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `start_date` datetime NOT NULL COMMENT '开始接诊时间',
  `end_date` datetime NULL DEFAULT NULL COMMENT '完成接诊时间，为空表示接诊中',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人系统用户ID',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '最后修改人系统用户ID',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_date` datetime NOT NULL COMMENT '最后修改时间',
  PRIMARY KEY (`record_id`) USING BTREE,
  UNIQUE INDEX `uk_med_outpatient_record_registration`(`registration_id` ASC) USING BTREE,
  INDEX `idx_med_outpatient_record_patient_end`(`patient_id` ASC, `end_date` ASC) USING BTREE,
  INDEX `idx_med_outpatient_record_doctor_start`(`doctor_id` ASC, `start_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '门诊病历' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of med_outpatient_record
-- ----------------------------

-- ----------------------------
-- Table structure for med_patient
-- ----------------------------
DROP TABLE IF EXISTS `med_patient`;
CREATE TABLE `med_patient`  (
  `patient_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '患者主键ID',
  `patient_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '患者业务编号',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '患者姓名',
  `gender` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '性别字典值',
  `birth_date` date NOT NULL COMMENT '出生日期',
  `id_type` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '证件类型字典值',
  `id_number` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '证件号码',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '患者手机号',
  `address` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '常住地址',
  `emergency_contact_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '紧急联系人姓名',
  `emergency_contact_relation` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '紧急联系人关系',
  `emergency_contact_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '紧急联系人手机号',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态：0停用，1启用',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人ID',
  `create_date` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_date` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '删除标记：0未删除，1已删除',
  PRIMARY KEY (`patient_id`) USING BTREE,
  UNIQUE INDEX `uk_med_patient_patient_no`(`patient_no` ASC) USING BTREE,
  UNIQUE INDEX `uk_med_patient_identity`(`id_type` ASC, `id_number` ASC) USING BTREE,
  INDEX `idx_med_patient_name`(`name` ASC) USING BTREE,
  INDEX `idx_med_patient_phone`(`phone` ASC) USING BTREE,
  INDEX `idx_med_patient_status`(`status` ASC) USING BTREE,
  INDEX `idx_med_patient_create_date`(`create_date` ASC) USING BTREE,
  INDEX `idx_med_patient_owner_active`(`creator_id` ASC, `del_flag` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '患者主档案' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of med_patient
-- ----------------------------

-- ----------------------------
-- Table structure for med_prescription
-- ----------------------------
DROP TABLE IF EXISTS `med_prescription`;
CREATE TABLE `med_prescription`  (
  `prescription_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '处方ID（UUID）',
  `prescription_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '处方编号，使用公共编码流水生成',
  `record_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '门诊病历ID',
  `registration_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '挂号单ID',
  `patient_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '患者ID',
  `doctor_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '开方医生ID',
  `prescription_type` smallint NOT NULL COMMENT '处方类型：10普通处方，20中药饮片处方（预留）',
  `status` smallint NOT NULL DEFAULT 0 COMMENT '状态：0草稿，10待审核，20审核通过，30审核不通过，40已作废',
  `current_version` int NOT NULL DEFAULT 0 COMMENT '当前已提交版本号，草稿未提交时为0',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '处方备注',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人系统用户ID',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '最后修改人系统用户ID',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_date` datetime NOT NULL COMMENT '最后修改时间',
  PRIMARY KEY (`prescription_id`) USING BTREE,
  UNIQUE INDEX `uk_med_prescription_no`(`prescription_no` ASC) USING BTREE,
  INDEX `idx_med_prescription_record_status`(`record_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_med_prescription_review`(`status` ASC, `update_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '处方当前主表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of med_prescription
-- ----------------------------

-- ----------------------------
-- Table structure for med_prescription_item
-- ----------------------------
DROP TABLE IF EXISTS `med_prescription_item`;
CREATE TABLE `med_prescription_item`  (
  `item_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '处方药品明细ID（UUID）',
  `prescription_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '处方ID',
  `sku_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '产品SKU ID',
  `sku_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SKU编码快照',
  `product_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '药品名称快照',
  `spec_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '药品规格快照',
  `dosage_form` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '剂型快照',
  `enterprise_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '生产企业名称快照',
  `approval_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '批准文号快照',
  `package_spec_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '包装规格快照',
  `pack_conversion` int NOT NULL COMMENT '每包装包含的最小单位数量快照',
  `min_unit_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '最小单位名称快照',
  `package_unit_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '包装单位名称快照',
  `allow_split` tinyint NOT NULL DEFAULT 0 COMMENT '是否允许拆零快照：0否，1是',
  `single_dose` decimal(12, 3) NOT NULL COMMENT '单次用量',
  `dose_unit` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '单次用量单位',
  `medication_route` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '给药途径字典值',
  `frequency` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用药频次枚举值',
  `course_days` int NOT NULL COMMENT '疗程天数',
  `total_min_quantity` decimal(14, 3) NOT NULL COMMENT '按最小单位计算的总量',
  `dispense_quantity` decimal(14, 3) NOT NULL COMMENT '最终发药数量',
  `dispense_unit` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '最终发药单位',
  `usage_instructions` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '用药说明',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '明细备注',
  `sort` int NOT NULL DEFAULT 0 COMMENT '处方内排序号',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人系统用户ID',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '最后修改人系统用户ID',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_date` datetime NOT NULL COMMENT '最后修改时间',
  PRIMARY KEY (`item_id`) USING BTREE,
  UNIQUE INDEX `uk_med_prescription_item_sku`(`prescription_id` ASC, `sku_id` ASC) USING BTREE,
  INDEX `idx_med_prescription_item_sort`(`prescription_id` ASC, `sort` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '处方当前药品明细' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of med_prescription_item
-- ----------------------------

-- ----------------------------
-- Table structure for med_prescription_submission
-- ----------------------------
DROP TABLE IF EXISTS `med_prescription_submission`;
CREATE TABLE `med_prescription_submission`  (
  `submission_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '处方提交版本ID（UUID）',
  `prescription_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '处方ID',
  `version` int NOT NULL COMMENT '处方提交版本号，从1递增',
  `submission_status` smallint NOT NULL DEFAULT 0 COMMENT '提交状态：0待审核，10审核通过，20审核不通过，30已撤回',
  `allergy_history` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '提交时患者过敏史快照',
  `submitted_by` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '提交人系统用户ID',
  `submitted_at` datetime NOT NULL COMMENT '提交时间',
  `reviewer_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '审核人系统用户ID',
  `review_opinion` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '审核意见',
  `reviewed_at` datetime NULL DEFAULT NULL COMMENT '审核时间',
  PRIMARY KEY (`submission_id`) USING BTREE,
  UNIQUE INDEX `uk_med_prescription_submission_version`(`prescription_id` ASC, `version` ASC) USING BTREE,
  INDEX `idx_med_prescription_submission_review`(`submission_status` ASC, `submitted_at` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '处方提交及审核版本' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of med_prescription_submission
-- ----------------------------

-- ----------------------------
-- Table structure for med_prescription_submission_diagnosis
-- ----------------------------
DROP TABLE IF EXISTS `med_prescription_submission_diagnosis`;
CREATE TABLE `med_prescription_submission_diagnosis`  (
  `submission_diagnosis_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '提交诊断快照ID（UUID）',
  `submission_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '处方提交版本ID',
  `diagnosis_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '疾病诊断档案ID快照',
  `icd_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ICD编码快照',
  `icd_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ICD名称快照',
  `is_primary` tinyint NOT NULL DEFAULT 0 COMMENT '是否主要诊断快照：0否，1是',
  `sort` int NOT NULL DEFAULT 0 COMMENT '诊断快照排序号',
  PRIMARY KEY (`submission_diagnosis_id`) USING BTREE,
  UNIQUE INDEX `uk_med_prescription_submission_diagnosis`(`submission_id` ASC, `diagnosis_id` ASC) USING BTREE,
  INDEX `idx_med_prescription_submission_diagnosis_sort`(`submission_id` ASC, `is_primary` ASC, `sort` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '处方提交诊断快照' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of med_prescription_submission_diagnosis
-- ----------------------------

-- ----------------------------
-- Table structure for med_prescription_submission_item
-- ----------------------------
DROP TABLE IF EXISTS `med_prescription_submission_item`;
CREATE TABLE `med_prescription_submission_item`  (
  `submission_item_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '提交药品快照ID（UUID）',
  `submission_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '处方提交版本ID',
  `sku_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '产品SKU ID快照',
  `sku_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SKU编码快照',
  `product_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '药品名称快照',
  `spec_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '药品规格快照',
  `dosage_form` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '剂型快照',
  `enterprise_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '生产企业名称快照',
  `approval_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '批准文号快照',
  `package_spec_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '包装规格快照',
  `pack_conversion` int NOT NULL COMMENT '包装换算系数快照',
  `min_unit_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '最小单位名称快照',
  `package_unit_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '包装单位名称快照',
  `allow_split` tinyint NOT NULL DEFAULT 0 COMMENT '是否允许拆零快照：0否，1是',
  `single_dose` decimal(12, 3) NOT NULL COMMENT '单次用量快照',
  `dose_unit` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '单次用量单位快照',
  `medication_route` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '给药途径快照',
  `frequency` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用药频次快照',
  `course_days` int NOT NULL COMMENT '疗程天数快照',
  `total_min_quantity` decimal(14, 3) NOT NULL COMMENT '最小单位总量快照',
  `dispense_quantity` decimal(14, 3) NOT NULL COMMENT '最终发药数量快照',
  `dispense_unit` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '最终发药单位快照',
  `usage_instructions` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '用药说明快照',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '明细备注快照',
  `sort` int NOT NULL DEFAULT 0 COMMENT '提交版本内排序号',
  PRIMARY KEY (`submission_item_id`) USING BTREE,
  UNIQUE INDEX `uk_med_prescription_submission_item_sku`(`submission_id` ASC, `sku_id` ASC) USING BTREE,
  INDEX `idx_med_prescription_submission_item_sort`(`submission_id` ASC, `sort` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '处方提交药品明细快照' ROW_FORMAT = Dynamic;

