-- Records of med_prescription_submission_item
-- ----------------------------

-- ----------------------------
-- Table structure for med_registration
-- ----------------------------
DROP TABLE IF EXISTS `med_registration`;
CREATE TABLE `med_registration`  (
  `registration_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '挂号单ID',
  `registration_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '挂号单编号，使用REG前缀业务序列生成',
  `patient_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联患者ID',
  `patient_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '患者编号快照',
  `patient_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '患者姓名快照，敏感信息',
  `patient_gender` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '患者性别字典值快照',
  `patient_birth_date` date NOT NULL COMMENT '患者出生日期快照',
  `patient_id_type` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '患者证件类型字典值快照',
  `patient_id_number` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '患者证件号码快照，敏感信息',
  `patient_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '患者手机号快照，敏感信息',
  `schedule_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联排班ID',
  `slot_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联号源时段ID',
  `doctor_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联医生ID',
  `doctor_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '医生姓名快照',
  `department_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联出诊科室ID',
  `department_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '出诊科室名称快照',
  `schedule_date` date NOT NULL COMMENT '就诊日期快照',
  `start_time` time NOT NULL COMMENT '号源开始时间快照',
  `end_time` time NOT NULL COMMENT '号源结束时间快照',
  `registration_type` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '挂号类型字典值快照',
  `registration_type_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '挂号类型名称快照',
  `registration_method` smallint NOT NULL COMMENT '挂号方式：0现场挂号，10预约挂号',
  `fee_rule_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '挂号费用规则ID快照',
  `fee_rule_version` int NULL DEFAULT NULL COMMENT '挂号费用规则版本快照',
  `fee_amount` decimal(10, 2) NOT NULL COMMENT '挂号费用金额快照',
  `status` smallint NOT NULL DEFAULT 0 COMMENT '挂号状态：0待支付，10已支付，30已签到，50已完成，60已取消，70爽约，80发起退款，90退款中，100退款完成',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建挂号单时填写的备注',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人用户ID',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '最后更新人用户ID',
  `create_date` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_date` datetime NULL DEFAULT NULL COMMENT '最后更新时间',
  PRIMARY KEY (`registration_id`) USING BTREE,
  UNIQUE INDEX `uk_med_registration_no`(`registration_no` ASC) USING BTREE,
  INDEX `idx_med_registration_patient_slot`(`patient_id` ASC, `slot_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_med_registration_visit_status`(`schedule_date` ASC, `status` ASC) USING BTREE,
  INDEX `idx_med_registration_department_date`(`department_id` ASC, `schedule_date` ASC) USING BTREE,
  INDEX `idx_med_registration_doctor_date`(`doctor_id` ASC, `schedule_date` ASC) USING BTREE,
  INDEX `idx_med_registration_create_date`(`create_date` ASC) USING BTREE,
  INDEX `idx_med_registration_owner_date`(`creator_id` ASC, `create_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '医疗挂号单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of med_registration
-- ----------------------------

-- ----------------------------
-- Table structure for med_registration_fee_rule
-- ----------------------------
DROP TABLE IF EXISTS `med_registration_fee_rule`;
CREATE TABLE `med_registration_fee_rule`  (
  `fee_rule_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '挂号费规则ID',
  `doctor_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '医生ID',
  `department_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '出诊科室ID',
  `registration_type` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '挂号类型，字典MED_REGISTRATION_TYPE',
  `fee_amount` decimal(10, 2) NOT NULL COMMENT '挂号费金额（元）',
  `effective_date` date NOT NULL COMMENT '生效日期（含）',
  `expiry_date` date NULL DEFAULT NULL COMMENT '失效日期（含），NULL表示长期有效',
  `version` int NOT NULL COMMENT '同一医生、科室和挂号类型下的版本号',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '调价说明或备注',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人ID',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '删除标记 0正常 1删除',
  PRIMARY KEY (`fee_rule_id`) USING BTREE,
  UNIQUE INDEX `uk_med_registration_fee_version`(`doctor_id` ASC, `department_id` ASC, `registration_type` ASC, `version` ASC) USING BTREE,
  INDEX `idx_med_registration_fee_period`(`doctor_id` ASC, `department_id` ASC, `registration_type` ASC, `effective_date` ASC, `expiry_date` ASC, `del_flag` ASC) USING BTREE,
  INDEX `idx_med_registration_fee_department`(`department_id` ASC, `effective_date` ASC, `expiry_date` ASC, `del_flag` ASC) USING BTREE,
  INDEX `idx_med_registration_fee_effective`(`effective_date` ASC, `expiry_date` ASC, `del_flag` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '挂号费版本规则' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of med_registration_fee_rule
-- ----------------------------

-- ----------------------------
-- Table structure for med_registration_log
-- ----------------------------
DROP TABLE IF EXISTS `med_registration_log`;
CREATE TABLE `med_registration_log`  (
  `log_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '挂号单日志ID',
  `registration_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联挂号单ID',
  `from_status` smallint NULL DEFAULT NULL COMMENT '变更前状态，状态码同挂号单状态字段，创建记录为空',
  `to_status` smallint NOT NULL COMMENT '变更后状态，状态码同挂号单状态字段',
  `operator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '操作人用户ID',
  `operated_at` datetime NOT NULL COMMENT '业务状态变更时间',
  `reason` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '取消或发起退款等业务原因',
  `refund_amount` decimal(10, 2) NULL DEFAULT NULL COMMENT '退款金额，发起退款时记录费用快照金额',
  PRIMARY KEY (`log_id`) USING BTREE,
  INDEX `idx_med_registration_log_order`(`registration_id` ASC, `operated_at` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '挂号单日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of med_registration_log
-- ----------------------------

-- ----------------------------
-- Table structure for med_schedule
-- ----------------------------
DROP TABLE IF EXISTS `med_schedule`;
CREATE TABLE `med_schedule`  (
  `schedule_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '实际排班ID',
  `template_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源周期模板ID，手工排班为空',
  `generation_batch_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源生成批次ID',
  `doctor_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '医生ID',
  `department_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '出诊科室ID',
  `registration_type` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '挂号类型，字典MED_REGISTRATION_TYPE',
  `schedule_date` date NOT NULL COMMENT '出诊日期',
  `start_time` time NOT NULL COMMENT '开始时间',
  `end_time` time NOT NULL COMMENT '结束时间',
  `fee_rule_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '发布时固化的挂号费规则ID',
  `fee_rule_version` int NULL DEFAULT NULL COMMENT '发布时固化的规则版本',
  `fee_amount` decimal(10, 2) NULL DEFAULT NULL COMMENT '发布时固化的挂号费金额（元）',
  `default_slot_quota` int NOT NULL DEFAULT 1 COMMENT '草稿生成时每半小时默认容量',
  `total_quota` int NOT NULL COMMENT '号源总量',
  `booked_quota` int NOT NULL DEFAULT 0 COMMENT '已预约号源数',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态 0草稿 1已发布 2停诊 3结束',
  `stop_reason` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '停诊原因',
  `published_at` datetime NULL DEFAULT NULL COMMENT '发布时间',
  `stopped_at` datetime NULL DEFAULT NULL COMMENT '停诊时间',
  `finished_at` datetime NULL DEFAULT NULL COMMENT '结束时间',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人ID',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '删除标记 0正常 1删除',
  PRIMARY KEY (`schedule_id`) USING BTREE,
  UNIQUE INDEX `uk_med_schedule_template_date`(`template_id` ASC, `schedule_date` ASC) USING BTREE,
  INDEX `idx_med_schedule_doctor_conflict`(`doctor_id` ASC, `schedule_date` ASC, `status` ASC, `del_flag` ASC, `start_time` ASC, `end_time` ASC) USING BTREE,
  INDEX `idx_med_schedule_department_date`(`department_id` ASC, `schedule_date` ASC, `status` ASC, `del_flag` ASC) USING BTREE,
  INDEX `idx_med_schedule_batch`(`generation_batch_id` ASC) USING BTREE,
  INDEX `idx_med_schedule_fee_rule`(`fee_rule_id` ASC, `fee_rule_version` ASC) USING BTREE,
  INDEX `idx_med_schedule_owner_active`(`creator_id` ASC, `del_flag` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '实际排班及费用号源快照' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of med_schedule
-- ----------------------------

-- ----------------------------
-- Table structure for med_schedule_auto_task
-- ----------------------------
DROP TABLE IF EXISTS `med_schedule_auto_task`;
CREATE TABLE `med_schedule_auto_task`  (
  `task_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '自动任务记录ID',
  `task_key` varchar(96) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '任务幂等键：任务类型+目标周',
  `task_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '任务类型 publish发布 generate生成',
  `target_week_start` date NOT NULL COMMENT '目标周开始日期（周一）',
  `target_week_end` date NOT NULL COMMENT '目标周结束日期（周日）',
  `status` tinyint NOT NULL COMMENT '状态 0成功 1部分成功 2失败 3执行中',
  `success_doctor_count` int NOT NULL DEFAULT 0 COMMENT '成功医生数',
  `failure_doctor_count` int NOT NULL DEFAULT 0 COMMENT '失败医生数',
  `details` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '失败医生及原因JSON',
  `executed_at` datetime NOT NULL COMMENT '执行时间',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`task_id`) USING BTREE,
  UNIQUE INDEX `uk_med_schedule_auto_task_key`(`task_key` ASC) USING BTREE,
  INDEX `idx_med_schedule_auto_task_week`(`target_week_start` ASC, `task_type` ASC, `status` ASC) USING BTREE,
  INDEX `idx_med_schedule_auto_task_executed`(`executed_at` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '出诊排班每周自动发布和生成任务记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of med_schedule_auto_task
-- ----------------------------

-- ----------------------------
-- Table structure for med_schedule_generation_batch
-- ----------------------------
DROP TABLE IF EXISTS `med_schedule_generation_batch`;
CREATE TABLE `med_schedule_generation_batch`  (
  `batch_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '排班生成批次ID',
  `idempotency_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户端幂等键',
  `request_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '规范化请求SHA256',
  `template_ids` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板ID列表JSON',
  `start_date` date NOT NULL COMMENT '生成开始日期（含）',
  `end_date` date NOT NULL COMMENT '生成结束日期（含）',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态 0处理中 1完成',
  `generated_count` int NOT NULL DEFAULT 0 COMMENT '生成数量',
  `skipped_count` int NOT NULL DEFAULT 0 COMMENT '因幂等已存在而跳过数量',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`batch_id`) USING BTREE,
  UNIQUE INDEX `uk_med_schedule_batch_idempotency`(`idempotency_key` ASC) USING BTREE,
  INDEX `idx_med_schedule_batch_date`(`start_date` ASC, `end_date` ASC, `create_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '排班批量生成幂等批次' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of med_schedule_generation_batch
-- ----------------------------

-- ----------------------------
-- Table structure for med_schedule_slot
-- ----------------------------
DROP TABLE IF EXISTS `med_schedule_slot`;
CREATE TABLE `med_schedule_slot`  (
  `slot_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '号源档位ID',
  `schedule_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '出诊排班ID',
  `start_time` time NOT NULL COMMENT '档位开始时间',
  `end_time` time NOT NULL COMMENT '档位结束时间',
  `quota` int NOT NULL COMMENT '档位可预约容量 0至99',
  `booked_quota` int NOT NULL DEFAULT 0 COMMENT '已预约数量',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人ID',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '删除标记 0正常 1删除',
  PRIMARY KEY (`slot_id`) USING BTREE,
  UNIQUE INDEX `uk_med_schedule_slot_time`(`schedule_id` ASC, `start_time` ASC, `del_flag` ASC) USING BTREE,
  INDEX `idx_med_schedule_slot_available`(`schedule_id` ASC, `start_time` ASC, `quota` ASC, `booked_quota` ASC, `del_flag` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '出诊排班半小时预约号源档位' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of med_schedule_slot
-- ----------------------------

-- ----------------------------
-- Table structure for med_schedule_template
-- ----------------------------
DROP TABLE IF EXISTS `med_schedule_template`;
CREATE TABLE `med_schedule_template`  (
  `template_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '周期排班模板ID',
  `template_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板名称',
  `doctor_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '医生ID',
  `department_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '出诊科室ID',
  `registration_type` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '挂号类型，字典MED_REGISTRATION_TYPE',
  `weekday` tinyint NOT NULL COMMENT '星期 1周一至7周日',
  `start_time` time NOT NULL COMMENT '开始时间',
  `end_time` time NOT NULL COMMENT '结束时间',
  `default_slot_quota` int NOT NULL DEFAULT 1 COMMENT '每半小时默认号源容量',
  `slot_quota_config` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '单档容量覆盖JSON',
  `total_quota` int NOT NULL COMMENT '模板号源总量',
  `effective_date` date NOT NULL COMMENT '模板生效日期（含）',
  `expiry_date` date NULL DEFAULT NULL COMMENT '模板失效日期（含），NULL表示长期有效',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态 0停用 1启用',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人ID',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '删除标记 0正常 1删除',
  PRIMARY KEY (`template_id`) USING BTREE,
  INDEX `idx_med_schedule_template_doctor`(`doctor_id` ASC, `weekday` ASC, `status` ASC, `del_flag` ASC, `effective_date` ASC, `expiry_date` ASC) USING BTREE,
  INDEX `idx_med_schedule_template_department`(`department_id` ASC, `status` ASC, `del_flag` ASC) USING BTREE,
  INDEX `idx_med_schedule_template_period`(`effective_date` ASC, `expiry_date` ASC, `status` ASC, `del_flag` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '周期排班模板' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of med_schedule_template
-- ----------------------------

-- ----------------------------
-- Table structure for med_schedule_template_weekday
-- ----------------------------
DROP TABLE IF EXISTS `med_schedule_template_weekday`;
CREATE TABLE `med_schedule_template_weekday`  (
  `template_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '周期排班模板ID',
  `weekday` tinyint NOT NULL COMMENT '星期 1周一至7周日',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`template_id`, `weekday`) USING BTREE,
  INDEX `idx_med_schedule_template_weekday`(`weekday` ASC, `template_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '周期排班模板适用星期' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of med_schedule_template_weekday
-- ----------------------------

-- ----------------------------
-- Table structure for med_visit_queue
-- ----------------------------
DROP TABLE IF EXISTS `med_visit_queue`;
CREATE TABLE `med_visit_queue`  (
  `queue_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '候诊记录ID（UUID）',
  `registration_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '挂号单ID',
  `schedule_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '实际排班ID，作为候诊队列边界',
  `queue_sequence` int UNSIGNED NOT NULL COMMENT '签到序号，同一实际排班内从1递增',
  `queue_status` smallint NOT NULL DEFAULT 0 COMMENT '候诊状态：0-候诊中，30-已完成',
  `call_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '叫号次数',
  `create_date` datetime NOT NULL COMMENT '候诊记录创建时间，即签到排号时间',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人系统用户ID',
  PRIMARY KEY (`queue_id`) USING BTREE,
  UNIQUE INDEX `uk_med_visit_queue_registration`(`registration_id` ASC) USING BTREE,
  UNIQUE INDEX `uk_med_visit_queue_schedule_sequence`(`schedule_id` ASC, `queue_sequence` ASC) USING BTREE,
  INDEX `idx_med_visit_queue_schedule_status_sequence`(`schedule_id` ASC, `queue_status` ASC, `queue_sequence` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '挂号单候诊队列表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of med_visit_queue
-- ----------------------------

-- ----------------------------
-- Table structure for pay_channel
-- ----------------------------
DROP TABLE IF EXISTS `pay_channel`;
CREATE TABLE `pay_channel`  (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '渠道配置ID(UUID带横线)',
  `channel_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '渠道配置名称(如\"微信支付-生产\")',
  `channel_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '渠道类型 wechat/alipay',
  `env_mode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '环境模式 development/testing/staging/production',
  `app_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '应用ID(微信/支付宝通用)',
  `extra_config` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '渠道差异化配置 JSON',
  `notify_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '支付回调地址',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '启用状态 0=禁用 1=启用',
  `is_default` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否默认 0=否 1=是',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `create_date` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_date` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` tinyint(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除标志 0=正常 1=已删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_channel_type_env`(`channel_type` ASC, `env_mode` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_update_date`(`update_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '支付渠道配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of pay_channel
-- ----------------------------

-- ----------------------------
-- Table structure for print_template
-- ----------------------------
DROP TABLE IF EXISTS `print_template`;
CREATE TABLE `print_template`  (
  `template_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '打印模板唯一标识',
  `document_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务单据类型，例如 PURCHASE_INBOUND；同一种单据类型只允许存在一条模板记录',
  `template_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '打印模板名称',
  `draft_layout` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '当前编辑中的模板布局草稿，保存模板版式、字段绑定、分页等设计数据',
  `published_layout` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '当前已发布并实际生效的模板布局；未发布时为空',
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板状态：DRAFT-草稿，PUBLISHED-已发布',
  `row_version` int NOT NULL DEFAULT 1 COMMENT '数据行版本号，用于并发更新时进行乐观锁校验',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人用户标识',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '最后更新人用户标识',
  `create_date` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_date` datetime NULL DEFAULT NULL COMMENT '最后更新时间',
  PRIMARY KEY (`template_id`) USING BTREE,
  UNIQUE INDEX `uk_print_template_document_type`(`document_type` ASC) USING BTREE,
  INDEX `idx_print_template_status`(`status` ASC) USING BTREE,
  INDEX `idx_print_template_update_date`(`update_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '业务单据打印模板；每种单据类型仅维护一条当前模板记录，不保存历史版本' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of print_template
-- ----------------------------

-- ----------------------------
-- Table structure for product_mp
-- ----------------------------
DROP TABLE IF EXISTS `product_mp`;
CREATE TABLE `product_mp`  (
  `mp_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '厂家产品ID',
  `mp_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'MP编码',
  `rp_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所属规格产品ID',
  `enterprise_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '生产企业ID',
  `approval_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '批准文号/注册证号/备案号',
  `approval_no_normalized` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '批准文号标准化值',
  `brand_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '品牌/商品名',
  `description` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '描述',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态: 0停用 1启用',
  `row_version` int NOT NULL DEFAULT 1 COMMENT '数据版本号',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人ID',
  `create_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '删除标记: 0正常 1删除',
  PRIMARY KEY (`mp_id`) USING BTREE,
  UNIQUE INDEX `uk_product_mp_code`(`mp_code` ASC) USING BTREE,
  UNIQUE INDEX `uk_product_mp_rp_enterprise_approval`(`rp_id` ASC, `enterprise_id` ASC, `approval_no_normalized` ASC, `del_flag` ASC) USING BTREE,
  INDEX `idx_product_mp_rp_status`(`rp_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_product_mp_enterprise`(`enterprise_id` ASC) USING BTREE,
  INDEX `idx_product_mp_update_date`(`update_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '厂家产品主数据表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of product_mp
-- ----------------------------

-- ----------------------------
-- Table structure for product_rp
-- ----------------------------
DROP TABLE IF EXISTS `product_rp`;
CREATE TABLE `product_rp`  (
  `rp_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '规格产品ID',
  `rp_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'RP编码',
  `spu_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所属通用产品ID',
  `spec_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '规格名称',
  `spec_name_normalized` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '规格名称标准化值',
  `dosage_form` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '剂型或形态',
  `strength_text` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '含量或规格文本',
  `description` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '描述',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态: 0停用 1启用',
  `row_version` int NOT NULL DEFAULT 1 COMMENT '数据版本号',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人ID',
  `create_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '删除标记: 0正常 1删除',
  PRIMARY KEY (`rp_id`) USING BTREE,
  UNIQUE INDEX `uk_product_rp_code`(`rp_code` ASC) USING BTREE,
  UNIQUE INDEX `uk_product_rp_spu_spec`(`spu_id` ASC, `spec_name_normalized` ASC, `del_flag` ASC) USING BTREE,
  INDEX `idx_product_rp_spu_status`(`spu_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_product_rp_update_date`(`update_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '规格产品主数据表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of product_rp
-- ----------------------------

-- ----------------------------
-- Table structure for product_sku
-- ----------------------------
DROP TABLE IF EXISTS `product_sku`;
CREATE TABLE `product_sku`  (
  `sku_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SKU ID',
  `sku_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SKU编码',
  `mp_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所属厂家产品ID',
  `package_spec_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '包装规格名称',
  `package_spec_name_normalized` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '包装规格名称标准归一化值(去空格/拼接/转小写)',
  `pack_conversion` int NOT NULL COMMENT '包装换算系数: 1个包装单位包含的最小单位数量',
  `min_unit_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '最小单位名称',
  `package_unit_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '包装单位名称',
  `carton_unit_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '大包装单位名称',
  `carton_conversion` int NOT NULL DEFAULT 1 COMMENT '大包装换算系数: 1个大包装单位包含的包装单位数量',
  `carton_spec_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '大包装规格名称',
  `full_chain_spec_name` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '全链路规格名称',
  `barcode` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '商品条码',
  `gtin` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'GTIN',
  `udi_di` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'UDI-DI',
  `allow_split` tinyint NOT NULL DEFAULT 0 COMMENT '是否允许拆零: 0否 1是',
  `trace_mode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NONE' COMMENT '追溯模式：NONE不启用追溯、SMALL按小码追溯',
  `description` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '描述',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态: 0停用 1启用',
  `row_version` int NOT NULL DEFAULT 1 COMMENT '数据版本号',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人ID',
  `create_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '删除标记: 0正常 1删除',
  PRIMARY KEY (`sku_id`) USING BTREE,
  UNIQUE INDEX `uk_product_sku_code`(`sku_code` ASC) USING BTREE,
  UNIQUE INDEX `uk_product_sku_mp_package_spec`(`mp_id` ASC, `package_spec_name_normalized` ASC, `del_flag` ASC) USING BTREE,
  INDEX `idx_product_sku_mp`(`mp_id` ASC) USING BTREE,
  INDEX `idx_product_sku_mp_status`(`mp_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_product_sku_status`(`status` ASC) USING BTREE,
  INDEX `idx_product_sku_update_date`(`update_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '包装品规主数据' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of product_sku
-- ----------------------------

-- ----------------------------
-- Table structure for product_sku_price
-- ----------------------------
DROP TABLE IF EXISTS `product_sku_price`;
CREATE TABLE `product_sku_price`  (
  `price_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SKU价格ID',
  `sku_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所属SKU ID',
  `price_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '价格类型',
  `scope_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '价格范围',
  `scope_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '范围对象ID，全局价为空',
  `currency_code` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'CNY' COMMENT '币种，第一版仅支持CNY',
  `price` decimal(18, 4) NOT NULL COMMENT '价格金额',
  `tax_included` tinyint NOT NULL DEFAULT 1 COMMENT '是否含税: 0否 1是',
  `effective_start` datetime NOT NULL COMMENT '生效开始时间',
  `effective_end` datetime NULL DEFAULT NULL COMMENT '生效结束时间，空表示长期有效',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态: 0停用 1启用',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `row_version` int NOT NULL DEFAULT 1 COMMENT '数据版本号',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人ID',
  `create_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '删除标记: 0正常 1删除',
  PRIMARY KEY (`price_id`) USING BTREE,
  INDEX `idx_product_sku_price_sku`(`sku_id` ASC) USING BTREE,
  INDEX `idx_product_sku_price_dimension`(`sku_id` ASC, `price_type` ASC, `scope_type` ASC, `scope_id` ASC, `del_flag` ASC) USING BTREE,
  INDEX `idx_product_sku_price_effective_start`(`effective_start` ASC) USING BTREE,
  INDEX `idx_product_sku_price_update_date`(`update_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'SKU价格资料表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of product_sku_price
-- ----------------------------

-- ----------------------------
-- Table structure for product_sku_price_tier
-- ----------------------------
DROP TABLE IF EXISTS `product_sku_price_tier`;
CREATE TABLE `product_sku_price_tier`  (
  `tier_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SKU价格阶梯ID',
  `price_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所属SKU价格ID',
  `min_quantity` int NOT NULL COMMENT '起始数量，按SKU包装单位计算',
  `max_quantity` int NULL DEFAULT NULL COMMENT '结束数量，空表示以上',
  `tier_price` decimal(18, 4) NOT NULL COMMENT '阶梯单价',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人ID',
  `create_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '删除标记: 0正常 1删除',
  PRIMARY KEY (`tier_id`) USING BTREE,
  INDEX `idx_product_sku_price_tier_price`(`price_id` ASC, `del_flag` ASC) USING BTREE,
  INDEX `idx_product_sku_price_tier_min`(`price_id` ASC, `min_quantity` ASC, `del_flag` ASC) USING BTREE,
  INDEX `idx_product_sku_price_tier_update_date`(`update_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'SKU价格阶梯表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of product_sku_price_tier
-- ----------------------------

-- ----------------------------
-- Table structure for product_spu
-- ----------------------------
DROP TABLE IF EXISTS `product_spu`;
CREATE TABLE `product_spu`  (
  `spu_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '通用产品ID',
  `spu_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SPU编码',
  `product_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '通用名称',
  `product_name_normalized` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '通用名称标准化值',
  `short_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '简称',
  `short_name_normalized` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '简称标准化值',
  `product_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '产品类型: DRUG/DEVICE/CONSUMABLE/FSMP/OTHER',
  `description` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '描述',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态: 0停用 1启用',
  `row_version` int NOT NULL DEFAULT 1 COMMENT '数据版本号',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `updater_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人ID',
  `create_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '删除标记: 0正常 1删除',
  PRIMARY KEY (`spu_id`) USING BTREE,
  UNIQUE INDEX `uk_product_spu_code`(`spu_code` ASC) USING BTREE,
  UNIQUE INDEX `uk_product_spu_name_type`(`product_name_normalized` ASC, `product_type` ASC, `del_flag` ASC) USING BTREE,
  INDEX `idx_product_spu_type_status`(`product_type` ASC, `status` ASC) USING BTREE,
  INDEX `idx_product_spu_update_date`(`update_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '通用产品主数据表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of product_spu
-- ----------------------------

-- ----------------------------
-- Table structure for sys_dept
-- ----------------------------
DROP TABLE IF EXISTS `sys_dept`;
CREATE TABLE `sys_dept`  (
  `dept_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '部门id,UUID格式',
  `dept_title` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '部门名称',
  `pid` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '父级id',
  `remark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `create_date` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_date` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `del_flag` int NULL DEFAULT 0 COMMENT '逻辑删除 0:正常  1:删除',
  `status` tinyint NULL DEFAULT 1 COMMENT '状态0=禁用,1=启用',
  PRIMARY KEY (`dept_id`) USING BTREE,
  INDEX `idx_sys_dept_active_parent`(`del_flag` ASC, `status` ASC, `pid` ASC, `dept_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '系统部门表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_dept
-- ----------------------------

-- ----------------------------
-- Table structure for sys_dict
-- ----------------------------
DROP TABLE IF EXISTS `sys_dict`;
CREATE TABLE `sys_dict`  (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字典id,UUID格式',
  `pid` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '父级字典id',
  `label` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '字典标题',
  `value` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '字典值',
  `type` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字典类型',
  `remark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `color` varchar(7) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '主题色,#2db7f5',
  `create_date` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_date` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `del_flag` tinyint NULL DEFAULT 0 COMMENT '逻辑删除 0:正常 1:删除',
  `status` int NULL DEFAULT 1 COMMENT '状态 0禁用 1启用',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '系统字典表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_dict
-- ----------------------------

-- ----------------------------
-- Table structure for sys_download_task
-- ----------------------------
DROP TABLE IF EXISTS `sys_download_task`;
CREATE TABLE `sys_download_task`  (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '任务ID',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '创建用户ID',
  `task_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '导出任务类型',
  `task_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '任务名称',
  `source_module` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '来源模块',
  `request_payload` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '导出条件JSON',
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'pending/running/succeeded/failed',
  `total_rows` bigint NOT NULL DEFAULT 0 COMMENT '总行数',
  `processed_rows` bigint NOT NULL DEFAULT 0 COMMENT '已处理行数',
  `progress` tinyint NOT NULL DEFAULT 0 COMMENT '进度百分比',
  `file_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '下载文件名',
  `file_path` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '服务器私有文件路径',
  `file_size` bigint NOT NULL DEFAULT 0 COMMENT '文件字节数',
  `error_message` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '失败原因',
  `completed_date` datetime NULL DEFAULT NULL COMMENT '完成时间',
  `expire_date` datetime NULL DEFAULT NULL COMMENT '文件过期时间',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_download_creator_created`(`creator_id` ASC, `create_date` ASC) USING BTREE,
  INDEX `idx_download_status_created`(`status` ASC, `create_date` ASC) USING BTREE,
  INDEX `idx_download_expire_date`(`expire_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '下载中心任务' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_download_task
-- ----------------------------

-- ----------------------------
-- Table structure for sys_file
-- ----------------------------
DROP TABLE IF EXISTS `sys_file`;
CREATE TABLE `sys_file`  (
  `file_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文件id,主健',
  `url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '文件访问URL',
  `name` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '存储文件名(UUID重命名)',
  `type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'MIME类型',
  `size` bigint NULL DEFAULT NULL COMMENT '文件大小(字节)',
  `file_ext` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '文件扩展名',
  `original_name` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '原始文件名',
  `path` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '文件存储路径(不含文件名)',
  `full_path` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '完整路径(file_path + file_name)',
  `thumbnail_path` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '缩略图路径 (图片专用)',
  `thumbnail_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '缩略图URL (图片专用)',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人id',
  `create_date` datetime NULL DEFAULT NULL COMMENT '创建日期',
  PRIMARY KEY (`file_id`) USING BTREE,
  INDEX `idx_sys_file_owner_date`(`creator_id` ASC, `create_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '系统文件表;通过上传的文件信息在这个表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_file
-- ----------------------------

-- ----------------------------
-- Table structure for sys_form_schema
-- ----------------------------
DROP TABLE IF EXISTS `sys_form_schema`;
CREATE TABLE `sys_form_schema`  (
  `form_schema_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '表单Schema ID',
  `schema_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Schema唯一标识',
  `schema_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Schema名称',
  `category` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类',
  `layout` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'single' COMMENT '表单布局 single单列 double双列 triple三列',
  `schema_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '可持久化Vben Form Schema JSON',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态 0禁用 1启用',
  `remark` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `create_date` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_date` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '删除标记 0正常 1删除',
  PRIMARY KEY (`form_schema_id`) USING BTREE,
  UNIQUE INDEX `uk_sys_form_schema_key`(`schema_key` ASC) USING BTREE,
  INDEX `idx_sys_form_schema_status`(`status` ASC, `del_flag` ASC) USING BTREE,
  INDEX `idx_sys_form_schema_category`(`category` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '独立表单Schema' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_form_schema
-- ----------------------------

-- ----------------------------
-- Table structure for sys_login_log
-- ----------------------------
DROP TABLE IF EXISTS `sys_login_log`;
CREATE TABLE `sys_login_log`  (
  `log_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `user_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `username` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '',
  `event_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `response_body` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  `response_truncated` tinyint NOT NULL DEFAULT 0,
  `http_status` int NOT NULL,
  `status` tinyint NOT NULL,
  `duration_ms` bigint NOT NULL DEFAULT 0,
  `ip` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '',
  `user_agent` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '',
  `content_type` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '',
  `create_date` datetime NOT NULL,
  PRIMARY KEY (`log_id`) USING BTREE,
  INDEX `idx_login_log_create_date`(`create_date` ASC) USING BTREE,
  INDEX `idx_login_log_status_date`(`status` ASC, `create_date` ASC) USING BTREE,
  INDEX `idx_login_log_username_date`(`username` ASC, `create_date` ASC) USING BTREE,
  INDEX `idx_login_log_ip_date`(`ip` ASC, `create_date` ASC) USING BTREE,
  INDEX `idx_sys_login_log_owner_date`(`user_id` ASC, `create_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '登录日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_login_log
-- ----------------------------

-- ----------------------------
-- Table structure for sys_menu
-- ----------------------------
DROP TABLE IF EXISTS `sys_menu`;
CREATE TABLE `sys_menu`  (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '菜单id,主键,UUID格式',
  `pid` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '上级菜单',
  `type` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '菜单类型,字典',
  `icon` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '图标',
  `active_icon` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '激活图标',
  `keep_alive` tinyint NULL DEFAULT 0 COMMENT '缓存标签页,0不缓存,1缓存',
  `hide_in_menu` tinyint NULL DEFAULT 0 COMMENT '在菜单中隐藏,0不隐藏,1隐藏',
  `hide_in_tab` tinyint NULL DEFAULT 0 COMMENT '在标签栏中隐藏,0不隐藏,1隐藏',
  `hide_in_breadcrumb` tinyint NULL DEFAULT 0 COMMENT '在面包屑中隐藏,0不隐藏,1隐藏',
  `hide_children_in_menu` tinyint NULL DEFAULT 0 COMMENT '隐藏子菜单0不隐藏,1隐藏',
  `badge` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '徽章内容',
  `badge_type` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '徽标类型',
  `badge_variants` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '徽标样式',
  `active_path` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '激活路径',
  `auth_code` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '权限码集合，多个权限码使用英文逗号分隔',
  `affix_tab` tinyint NULL DEFAULT 0 COMMENT '固定在标签0不固定,1固定',
  `component` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '页面组件路径',
  `title` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标题',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '路由名称，按钮为空',
  `path` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '路由地址',
  `status` tinyint NULL DEFAULT 1 COMMENT '状态1启用0禁用',
  `link` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '外链跳转路径',
  `iframe_src` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '内嵌页面的 iframe 地址',
  `order` tinyint NULL DEFAULT 0 COMMENT '用于路由->菜单排序',
  `max_num_of_open_tab` tinyint NULL DEFAULT NULL COMMENT '标签页最大打开数量(仅在打开同名标签页时生效)',
  `affix_tab_order` tinyint NULL DEFAULT 0 COMMENT '固定标签页的排序',
  `no_basic_layout` tinyint NULL DEFAULT 0 COMMENT '无基础布局，0=否 1=是',
  `ignore_access` tinyint NOT NULL DEFAULT 0 COMMENT '是否忽略访问鉴权：0否，1是',
  `open_in_new_window` tinyint NULL DEFAULT 0 COMMENT '在新窗口打开页面 0=否 1=是',
  `dom_cached` tinyint NULL DEFAULT 0 COMMENT '用于配置当前路由是否要将route对应dom元素缓存起来 0=否 1=是',
  `query` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '额外的路由参数',
  `menu_visible_with_forbidden` tinyint NULL DEFAULT 0 COMMENT '菜单可以看到，但是访问会被重定向到403',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人id',
  `creator_name` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人姓名',
  `create_date` datetime NULL DEFAULT NULL COMMENT '创建日期',
  `update_date` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `del_flag` tinyint NULL DEFAULT 0 COMMENT '逻辑删除 0:正常  1:删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '系统权限菜单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_menu
-- ----------------------------

-- ----------------------------
-- Table structure for sys_menu_message
-- ----------------------------
DROP TABLE IF EXISTS `sys_menu_message`;
CREATE TABLE `sys_menu_message`  (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息记录ID',
  `user_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '接收用户ID',
  `menu_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '目标菜单ID',
  `title` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息标题',
  `content` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息内容',
  `read_at` datetime NULL DEFAULT NULL COMMENT '已读时间，NULL表示未读',
  `create_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_sys_menu_message_user_unread`(`user_id` ASC, `read_at` ASC) USING BTREE,
  INDEX `idx_sys_menu_message_user_menu_unread`(`user_id` ASC, `menu_id` ASC, `read_at` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '用户菜单消息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_menu_message
-- ----------------------------

-- ----------------------------
-- Table structure for sys_operation_log
-- ----------------------------
DROP TABLE IF EXISTS `sys_operation_log`;
CREATE TABLE `sys_operation_log`  (
  `log_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `user_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `username` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '',
  `real_name` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '',
  `request_method` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `request_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `query_params` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  `request_body` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  `response_body` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  `query_truncated` tinyint NOT NULL DEFAULT 0,
  `request_truncated` tinyint NOT NULL DEFAULT 0,
  `response_truncated` tinyint NOT NULL DEFAULT 0,
  `http_status` int NOT NULL,
  `status` tinyint NOT NULL,
  `duration_ms` bigint NOT NULL DEFAULT 0,
  `ip` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '',
  `user_agent` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '',
  `content_type` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '',
  `create_date` datetime NOT NULL,
  PRIMARY KEY (`log_id`) USING BTREE,
  INDEX `idx_operation_log_create_date`(`create_date` ASC) USING BTREE,
  INDEX `idx_operation_log_status_date`(`status` ASC, `create_date` ASC) USING BTREE,
  INDEX `idx_operation_log_username_date`(`username` ASC, `create_date` ASC) USING BTREE,
  INDEX `idx_operation_log_url_date`(`request_url`(128) ASC, `create_date` ASC) USING BTREE,
  INDEX `idx_sys_operation_log_owner_date`(`user_id` ASC, `create_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '操作日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_operation_log
-- ----------------------------

-- ----------------------------
-- Table structure for sys_param
-- ----------------------------
DROP TABLE IF EXISTS `sys_param`;
CREATE TABLE `sys_param`  (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '参数ID(UUID带横线)',
  `param_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '参数键(点分命名,全局唯一)',
  `param_value` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '参数值(字符串存储,按 param_type 解释)',
  `param_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '参数类型 string/number/boolean/json',
  `is_public` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否公开 0=否 1=是',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `create_date` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_date` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` tinyint(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除标志 0=正常 1=已删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_param_key_del`(`param_key` ASC, `del_flag` ASC) USING BTREE,
  INDEX `idx_is_public`(`is_public` ASC) USING BTREE,
  INDEX `idx_update_date`(`update_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '系统参数表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_param
-- ----------------------------

-- ----------------------------
-- Table structure for sys_role
-- ----------------------------
DROP TABLE IF EXISTS `sys_role`;
CREATE TABLE `sys_role`  (
  `role_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '角色id,UUID格式',
  `role_title` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '角色名称',
  `remark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `data_scope` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'self' COMMENT '数据范围:all,customDepartment,department,departmentAndChildren,self,none',
  `status` tinyint NULL DEFAULT 1 COMMENT '状态0=禁用,1=启用',
  `create_date` datetime NULL DEFAULT NULL COMMENT '创建日期',
  `update_date` datetime NULL DEFAULT NULL COMMENT '修改日期',
  `del_flag` tinyint NULL DEFAULT 0 COMMENT '逻辑删除 0:正常  1:删除',
  PRIMARY KEY (`role_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '系统角色' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_role
-- ----------------------------

-- ----------------------------
-- Table structure for sys_role_dept
-- ----------------------------
DROP TABLE IF EXISTS `sys_role_dept`;
CREATE TABLE `sys_role_dept`  (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键ID,UUID格式',
  `role_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '角色ID',
  `dept_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '自定义数据范围部门ID',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_sys_role_dept_role_dept`(`role_id` ASC, `dept_id` ASC) USING BTREE,
  INDEX `idx_sys_role_dept_dept`(`dept_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '角色自定义数据范围部门关联表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of sys_role_dept
-- ----------------------------

-- ----------------------------
-- Table structure for sys_role_menu
-- ----------------------------
DROP TABLE IF EXISTS `sys_role_menu`;
CREATE TABLE `sys_role_menu`  (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键ID,UUID格式',
  `role_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '角色ID',
  `menu_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '菜单ID',
  `create_date` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_date` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `del_flag` int NULL DEFAULT 0 COMMENT '逻辑删除 0:正常 1:删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '角色权限关联菜单表' ROW_FORMAT = Dynamic;

