-- Records of sys_user_role
-- ----------------------------

-- ----------------------------
-- Table structure for wf_process_copy
-- ----------------------------
DROP TABLE IF EXISTS `wf_process_copy`;
CREATE TABLE `wf_process_copy`  (
  `copy_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '抄送记录id',
  `node_instance_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '节点实例ID',
  `instance_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流程实例id',
  `node_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '节点id',
  `node_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '节点名称快照',
  `receiver_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '接收人id',
  `receiver_name` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '接收人名称快照',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态:0未读 1已读',
  `read_date` datetime NULL DEFAULT NULL COMMENT '已读时间',
  `create_date` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0正常 1删除',
  PRIMARY KEY (`copy_id`) USING BTREE,
  INDEX `idx_wf_copy_instance_id`(`instance_id` ASC) USING BTREE,
  INDEX `idx_wf_copy_receiver_id`(`receiver_id` ASC) USING BTREE,
  INDEX `idx_wf_copy_status`(`status` ASC) USING BTREE,
  INDEX `idx_wf_copy_node_instance`(`node_instance_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '流程抄送记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of wf_process_copy
-- ----------------------------

-- ----------------------------
-- Table structure for wf_process_definition
-- ----------------------------
DROP TABLE IF EXISTS `wf_process_definition`;
CREATE TABLE `wf_process_definition`  (
  `definition_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流程定义id,UUID格式',
  `definition_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流程标识,系统内唯一',
  `definition_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流程名称',
  `category` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '流程分类',
  `status` tinyint NULL DEFAULT 0 COMMENT '状态:0草稿 1已发布 2已停用',
  `version` int NULL DEFAULT 0 COMMENT '发布版本号',
  `flow_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT 'LogicFlow画布JSON',
  `form_schema_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联表单Schema ID',
  `remark` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `creator_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人id',
  `create_date` datetime NULL DEFAULT NULL COMMENT '创建日期',
  `update_date` datetime NULL DEFAULT NULL COMMENT '修改日期',
  `del_flag` tinyint NULL DEFAULT 0 COMMENT '逻辑删除 0:正常 1:删除',
  PRIMARY KEY (`definition_id`) USING BTREE,
  INDEX `idx_wf_process_definition_key`(`definition_key` ASC) USING BTREE,
  INDEX `idx_wf_process_definition_status`(`status` ASC) USING BTREE,
  INDEX `idx_wf_process_definition_category`(`category` ASC) USING BTREE,
  INDEX `idx_wf_process_definition_form_schema_id`(`form_schema_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '流程定义表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of wf_process_definition
-- ----------------------------

-- ----------------------------
-- Table structure for wf_process_instance
-- ----------------------------
DROP TABLE IF EXISTS `wf_process_instance`;
CREATE TABLE `wf_process_instance`  (
  `instance_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流程实例id',
  `instance_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流程实例编号',
  `definition_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流程定义id',
  `definition_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流程标识快照',
  `definition_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流程名称快照',
  `definition_version` int NOT NULL COMMENT '流程定义版本快照',
  `title` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '实例标题',
  `business_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联业务唯一标识',
  `starter_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '发起人id',
  `starter_name` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '发起人名称快照',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态:0运行中 1已完成 2已驳回 3已撤销',
  `variables` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流程变量JSON',
  `flow_snapshot` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流程定义画布快照',
  `form_snapshot` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '发起时的流程表单结构快照JSON',
  `form_layout` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'single' COMMENT '发起时的表单布局快照',
  `start_date` datetime NULL DEFAULT NULL COMMENT '开始时间',
  `end_date` datetime NULL DEFAULT NULL COMMENT '结束时间',
  `create_date` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_date` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0正常 1删除',
  PRIMARY KEY (`instance_id`) USING BTREE,
  UNIQUE INDEX `uk_wf_process_instance_no`(`instance_no` ASC) USING BTREE,
  INDEX `idx_wf_instance_definition_id`(`definition_id` ASC) USING BTREE,
  INDEX `idx_wf_instance_business_key`(`business_key` ASC) USING BTREE,
  INDEX `idx_wf_instance_starter_id`(`starter_id` ASC) USING BTREE,
  INDEX `idx_wf_instance_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '流程实例表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of wf_process_instance
-- ----------------------------

-- ----------------------------
-- Table structure for wf_process_instance_sequence
-- ----------------------------
DROP TABLE IF EXISTS `wf_process_instance_sequence`;
CREATE TABLE `wf_process_instance_sequence`  (
  `prefix` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流程分类前缀',
  `business_date` date NOT NULL COMMENT '业务日期',
  `current_value` int UNSIGNED NOT NULL COMMENT '当前流水号',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`prefix`, `business_date`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '流程实例编号每日流水' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of wf_process_instance_sequence
-- ----------------------------

-- ----------------------------
-- Table structure for wf_process_node_instance
-- ----------------------------
DROP TABLE IF EXISTS `wf_process_node_instance`;
CREATE TABLE `wf_process_node_instance`  (
  `node_instance_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '节点实例ID',
  `instance_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流程实例ID',
  `node_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流程节点ID',
  `node_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流程节点名称快照',
  `node_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '节点类型',
  `sequence` int NOT NULL COMMENT '实例内展示顺序',
  `route_version` int NOT NULL COMMENT '路径版本',
  `status` tinyint NOT NULL COMMENT '0预计 1处理中 2完成 3终止 4已替换',
  `approval_mode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '审批方式 any/all',
  `branch_edge_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '条件节点命中连线ID',
  `actor_ids` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '预计参与人ID数组JSON',
  `actor_names` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '预计参与人名称数组JSON',
  `field_permissions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '节点字段权限快照JSON',
  `start_date` datetime NULL DEFAULT NULL COMMENT '节点到达时间',
  `end_date` datetime NULL DEFAULT NULL COMMENT '节点结束时间',
  `create_date` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_date` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`node_instance_id`) USING BTREE,
  INDEX `idx_wf_node_instance_instance_sequence`(`instance_id` ASC, `sequence` ASC) USING BTREE,
  INDEX `idx_wf_node_instance_instance_status`(`instance_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_wf_node_instance_route`(`instance_id` ASC, `route_version` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '流程节点实例' ROW_FORMAT = Dynamic;

