-- Records of wf_process_record
-- ----------------------------

-- ----------------------------
-- Table structure for wf_process_task
-- ----------------------------
DROP TABLE IF EXISTS `wf_process_task`;
CREATE TABLE `wf_process_task`  (
  `task_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '审批任务id',
  `task_group_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '同次进入审批节点的任务组id',
  `node_instance_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '节点实例ID',
  `instance_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流程实例id',
  `node_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'LogicFlow节点id',
  `node_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '节点名称快照',
  `assignee_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '审批人id',
  `assignee_name` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '审批人名称快照',
  `approval_mode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'any' COMMENT '审批方式:any或签 all会签',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态:0待处理 1已通过 2已驳回 3已取消',
  `comment` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '审批意见',
  `finish_date` datetime NULL DEFAULT NULL COMMENT '处理时间',
  `create_date` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_date` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0正常 1删除',
  PRIMARY KEY (`task_id`) USING BTREE,
  INDEX `idx_wf_task_group_id`(`task_group_id` ASC) USING BTREE,
  INDEX `idx_wf_task_instance_id`(`instance_id` ASC) USING BTREE,
  INDEX `idx_wf_task_assignee_id`(`assignee_id` ASC) USING BTREE,
  INDEX `idx_wf_task_status`(`status` ASC) USING BTREE,
  INDEX `idx_wf_task_node_instance`(`node_instance_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '流程审批任务表' ROW_FORMAT = Dynamic;

